import json, re
from pathlib import Path

manifest = json.loads(Path('/mnt/data/LSF/results/financebench/agentic_rule_full_data_gpt54_adaptive/all_docs/q10_what_is_the_address_of_principal_executive_offices_and_zip_c.manifest.json').read_text())
state_map = {
    'AL':'Alabama','AK':'Alaska','AZ':'Arizona','AR':'Arkansas','CA':'California','CO':'Colorado','CT':'Connecticut','DE':'Delaware','FL':'Florida','GA':'Georgia','HI':'Hawaii','ID':'Idaho','IL':'Illinois','IN':'Indiana','IA':'Iowa','KS':'Kansas','KY':'Kentucky','LA':'Louisiana','ME':'Maine','MD':'Maryland','MA':'Massachusetts','MI':'Michigan','MN':'Minnesota','MS':'Mississippi','MO':'Missouri','MT':'Montana','NE':'Nebraska','NV':'Nevada','NH':'New Hampshire','NJ':'New Jersey','NM':'New Mexico','NY':'New York','NC':'North Carolina','ND':'North Dakota','OH':'Ohio','OK':'Oklahoma','OR':'Oregon','PA':'Pennsylvania','RI':'Rhode Island','SC':'South Carolina','SD':'South Dakota','TN':'Tennessee','TX':'Texas','UT':'Utah','VT':'Vermont','VA':'Virginia','WA':'Washington','WV':'West Virginia','WI':'Wisconsin','WY':'Wyoming','DC':'District of Columbia'}
state_names={v.lower() for v in state_map.values()}
country_names={'united kingdom','jersey','england','ireland','canada','australia'}
street_words=('street','st.','avenue','ave.','road','rd.','boulevard','blvd.','drive','dr.','lane','ln.','way','parkway','pkwy','plaza','place','center','centre','circle','court','suite','tower','box')


def load_lines(path):
    text = Path(path).read_text(encoding='utf-8', errors='ignore')
    pages = re.split(r'\\f+', text)
    out=[]
    for pno, page in enumerate(pages, start=1):
        for lno, line in enumerate(page.splitlines(), start=1):
            out.append({'page_no':pno, 'line_no':lno, 'text':line})
    return out

def norm(s):
    s=str(s or '')
    s=s.replace('\\u00a0',' ')
    s=s.replace('\\u2019', \"'\")
    s=re.sub(r'\\s+', ' ', s)
    return s.strip()

def strip_label(s):
    s=norm(s)
    s=re.sub(r'\\(?address of principal executive offices\\)?', '', s, flags=re.I)
    s=re.sub(r'\\(?zip code\\)?', '', s, flags=re.I)
    s=re.sub(r'\\(?registrant.?s telephone number.*', '', s, flags=re.I)
    s=re.sub(r'\\(?telephone number.*', '', s, flags=re.I)
    s=re.sub(r'"'^[:'"\\-–—\\s]+|[:\\-–—\\s]+"'$'"', '', s)
    return norm(s).strip(' ,;')

def is_zip_label(t):
    low=norm(t).lower().strip('() ')
    return low=='zip code'

def is_anchor_line(t):
    low=norm(t).lower()
    return 'principal executive offices' in low

def is_labelish(t):
    low=norm(t).lower().strip()
    if not low:
        return False
    boiler = [
        'state or other jurisdiction', 'incorporation or organization', 'incorporation)',
        'i.r.s. employer', 'irs employer', 'identification no', 'commission file',
        'registrant\\'s telephone number', 'registrant’s telephone number', 'telephone number',
        'securities registered', 'title of each class', 'trading symbol', 'name of each exchange',
        'exact name of registrant', 'former name', 'for the transition period', 'annual report', 'quarterly report'
    ]
    return any(x in low for x in boiler)

def is_postal_only(t):
    s=strip_label(t)
    return bool(re.fullmatch(r'\\d{5}(?:-\\d{4})?', s) or re.fullmatch(r'[A-Z]{1,2}\\d[A-Z\\d]?\\s*\\d[A-Z]{2}', s, re.I))

def is_state_only(t):
    s=strip_label(t).rstrip('.')
    if not s:
        return False
    return s.upper() in state_map or s.lower() in state_names

def is_country_only(t):
    s=strip_label(t).lower()
    return s in country_names

def looks_address_component(t):
    s=strip_label(t)
    if not s:
        return False
    low=s.lower()
    if is_postal_only(s) or is_state_only(s) or is_country_only(s):
        return True
    if re.fullmatch(r'\\(?\\d{3}\\)?[\\s./-]*\\d{3}[\\s./-]*\\d{4}', s):
        return False
    if any(x in low for x in ('telephone', 'registrant', 'commission file', 'employer identification', 'exact name')):
        return False
    if any(w in low for w in street_words):
        return True
    if ',' in s:
        return True
    if re.search(r'\\d', s):
        return True
    if len(s.split()) <= 4:
        return True
    return False

def join_parts(parts):
    out=''
    prev=''
    for p in parts:
        p=strip_label(p)
        if not p:
            continue
        if not out:
            out=p
        elif is_postal_only(p):
            out = out.rstrip(', ') + ' ' + p
        elif is_state_only(p):
            if out.endswith(','):
                out += ' ' + p
            else:
                out += ', ' + p
        elif out.endswith(','):
            out += ' ' + p
        else:
            out += ', ' + p
        prev=p
    out=re.sub(r',\\s*,+', ', ', out)
    out=re.sub(r'\\s+,', ',', out)
    out=re.sub(r'\\s+', ' ', out).strip(' ,')
    return out

def extract(lines):
    anchors=[]
    for i,l in enumerate(lines):
        if is_anchor_line(l['text']):
            anchors.append(i)
        elif i+1 < len(lines) and lines[i+1]['page_no']==l['page_no']:
            comb = norm(l['text']) + ' ' + norm(lines[i+1]['text'])
            if 'principal executive offices' in comb.lower() and ('address' in comb.lower() or 'principal' in norm(l['text']).lower()):
                anchors.append(i if 'principal executive offices' in norm(l['text']).lower() else i+1)
    if not anchors:
        return ''
    cand=min(anchors, key=lambda i:(lines[i]['page_no'], lines[i]['line_no']))
    page=lines[cand]['page_no']
    parts=[]
    cand_clean=strip_label(lines[cand]['text'])
    if cand_clean and looks_address_component(cand_clean):
        parts.append(cand_clean)
    saw_addr=bool(parts)
    j=cand-1
    skipped_after_addr=0
    while j>=0 and len(parts)<6:
        line=lines[j]
        if line['page_no']"'!=page:
            break
        text=norm(line['"'text'])
        clean=strip_label(text)
        if not clean:
            if saw_addr:
                skipped_after_addr += 1
                if skipped_after_addr >= 3:
                    break
            j-=1
            continue
        if is_zip_label(text):
            j-=1
            continue
        if is_anchor_line(text):
            break
        if is_labelish(text):
            if saw_addr:
                break
            j-=1
            continue
        if re.fullmatch(r'\\(?\\d{3}\\)?[\\s./-]*\\d{3}[\\s./-]*\\d{4}', clean):
            if saw_addr:
                break
            j-=1
            continue
        if looks_address_component(text):
            parts.insert(0, clean)
            saw_addr=True
            skipped_after_addr=0
        elif saw_addr:
            break
        j-=1
    if not parts:
        return ''
    return join_parts(parts)

def canon(s):
    s=norm(s).lower()
    s=s.replace('st.', 'st').replace('rd.', 'rd').replace('ave.', 'ave').replace('dr.', 'dr')
    s=s.replace(' s.w. ', ' sw ').replace(' n.w. ', ' nw ')
    s=s.replace('s.w.', 'sw').replace('n.w.', 'nw').replace('n.e.', 'ne').replace('s.e.', 'se')
    s=re.sub(r'\\s*,\\s*', ', ', s)
    s=re.sub(r'\\s+', ' ', s)
    s=re.sub(r', (?=\\d{5}(?:-\\d{4})?"'$)'"', ' ', s)
    s=re.sub(r', (?=[a-z]{1,2}\\d[a-z\\d]?\\s*\\d[a-z]{2}"'$)'"', ' ', s)
    return s.strip(' ,')

exact=0
contains=0
fails=[]
for entry in manifest['documents']:
    pred=extract(load_lines(entry['doc_path']))
    gt=entry['ground_truth'] or ''
    cpred=canon(pred)
    cgt=canon(gt)
    ok = cpred==cgt
    cont = cgt and cgt in cpred
    exact += ok
    contains += cont
    if not cont:
        fails.append((entry['doc_name'], gt, pred))
print('docs', len(manifest['documents']))
print('exact', exact)
print('contains', contains)
print('failure_count', len(fails))
for doc,gt,pred in fails[:30]:
    print('---', doc)
    print('GT  :', gt)
    print('PRED:', pred)
